import itertools
import unittest

from ledger import api, csv_bank_import


class BankCsvTests(unittest.TestCase):
    parsers = (api.parse_bank_csv, csv_bank_import.parse_bank_csv)

    def test_header_orders_and_signed_amounts(self):
        values = {\"reference\": \"  ref  \", \"amount\": \"+0012\", \"memo\": \" memo \"}
        for headers in itertools.permutations(values):
            text = \",\".join(headers) + \"\\n\" + \",\".join(values[h] for h in headers)
            for parse in self.parsers:
                with self.subTest(headers=headers, parse=parse):
                    self.assertEqual(parse(text), [
                        {\"reference\": \"  ref  \", \"amount\": 12, \"memo\": \" memo \"}])

    def test_bom_quotes_newlines_and_crlf(self):
        text = '\\ufeffreference,amount,memo\\r\\n\"ref,1\",-12,\"first, line\\r\\nsecond \"\"quoted\"\" line\"\\r\\n,0,\\r\\n'
        expected = [
            {\"reference\": \"ref,1\", \"amount\": -12,
             \"memo\": 'first, line\\r\\nsecond \"quoted\" line'},
            {\"reference\": \"\", \"amount\": 0, \"memo\": \"\"},
        ]
        for parse in self.parsers:
            self.assertEqual(parse(text), expected)

    def test_header_only(self):
        for parse in self.parsers:
            self.assertEqual(parse(\"reference,amount,memo\"), [])
            self.assertEqual(parse(\"\\ufeffmemo,reference,amount\\r\\n\"), [])

    def test_invalid_input(self):
        invalid = [
            \"\", \"\\ufeff\", \"\\n\", \"reference,amount\",
            \"reference,amount,memo,extra\", \"reference,amount,amount\",
            \"reference,amount,Memo\",
            \"reference,amount,memo\\na,1\",
            \"reference,amount,memo\\na,1,m,extra\",
            \"reference,amount,memo\\n\\n\",
            'reference,amount,memo\\na,1,\"unterminated',
            'reference,amount,memo\\na,1,\"memo\"junk',
            'reference,amount,\"memo',
        ]
        for amount in (\"\", \"+\", \"-\", \"1.0\", \"1e2\", \" 1\", \"1 \", \"1_000\", \"１２\"):
            invalid.append(\"reference,amount,memo\\na,\" + amount + \",memo\")
        for text in invalid:
            for parse in self.parsers:
                with self.subTest(text=text, parse=parse):
                    with self.assertRaises(ValueError):
                        parse(text)
EOF
python -m unittest discover -s tests -v"
